typedef struct Token {
    TokType tag;
    orbit_string text;
    orbit_int line;
    orbit_int col;
    orbit_int start;
    orbit_int len;
} Token;
#define Token(...) (Token*)orbit_model_Token_create(arena, __VA_ARGS__)
static inline Token* orbit_model_Token_create(OrbitArena* arena_, TokType tag, orbit_string text, orbit_int line, orbit_int col, orbit_int start, orbit_int len) {
    Token* m = (Token*)orbit_alloc(arena_, sizeof(Token));
    m->tag = tag;
    m->text = text;
    m->line = line;
    m->col = col;
    m->start = start;
    m->len = len;
    return m;
}

