void doctorPrintGates(OrbitArena* arena) {
    print("%s", "gates: doctor never runs these itself; run them from the repository root:");
    print("%s", "  python scripts/verify_seed.py --cc <gcc-or-clang> --emit-fixed-point <path-to-orbit>");
    print("%s", "  python scripts/parity_selfhost.py --cc <gcc-or-clang> --compiler <path-to-orbit>");
    print("%s", "  python scripts/test_suite.py --cc <gcc-or-clang> --compiler <path-to-orbit>");
    return;
}

void doctorPrintHelp(OrbitArena* arena) {
    print("%s", "Usage: orbit doctor [dir] [options]");
    print("%s", "");
    print("%s", "Scans .orb files under [dir] (default: the current directory) without changing them.");
    print("%s", "  --fix           Apply the fixes doctor knows how to make.");
    print("%s", "  --unsafe        Also apply the structural fixes; off by default.");
    print("%s", "  --verify-build  Check each fixed file compiles to C (on by default with --fix).");
    print("%s", "  --fast          Skip that C check; the front end is still checked.");
    print("%s", "  --dry-run       Report what --fix would change, and change nothing.");
    print("%s", "  --only CODES    Only these codes, e.g. --only D006,D007.");
    print("%s", "  --skip CODES    Every code but these.");
    print("%s", "  --min-severity warning|error  Hide anything below this severity.");
    print("%s", "  --baseline FILE Print findings listed in FILE but do not fail on them.");
    print("%s", "  --telemetry FILE A ledger snapshot to check routes against; defaults to");
    print("%s", "                  $ORBIT_LEDGER_OUT. Absent, D031-D033 stay silent.");
    print("%s", "  --budget-doc FILE  The ENGINEERING.md whose latency budget D033 enforces;");
    print("%s", "                      defaults to ./ENGINEERING.md.");
    print("%s", "  --quiet         Findings (and fixes) only; no summaries or gate list.");
    print("%s", "  --verbose       Also print the scan scope, the per-phase timings, and the gate list.");
    print("%s", "  --format text|json  Output format; json is a JSON array on stdout.");
    print("%s", "  --color always|never|auto  ANSI colors (auto honors NO_COLOR/TERM).");
    print("%s", "");
    print("%s", "Exit codes: 0 clean, 1 findings, 2 usage.");
    return;
}

void doctorUsage(OrbitArena* arena) {
    orbit_os_write_stderr_selfhost((orbit_string)("Usage: orbit doctor [dir] [options]\nRun `orbit doctor --help` for details.\n"));
    return;
}

